'use client';

import React, { Suspense } from 'react';
import { X } from 'lucide-react';
import { VIEW_COMPONENTS } from '@/lib/studio/viewRegistry.components';

/**
 * NativePanelMount — mounts a panel's COMPILED-FROM-.holo native component (from VIEW_COMPONENTS,
 * generated by compile-view-registry.ts from an @native_panel .holo) into the right rail, in place
 * of the hand-written React panel. The native component is the chrome-less readout body; this
 * wrapper owns the chrome the body can't yet express (a close button).
 *
 * Fail-safe by construction (mirrors compile-holo-pages fail-soft): if the native component is
 * absent (VIEW_COMPONENTS[id] undefined — e.g. the .native.tsx wasn't generated) OR throws at
 * runtime, it renders the hand-written `fallback` panel — so a bad native compile can never blank
 * the rail. This is the first live consumer of VIEW_COMPONENTS (paper "Compile the Surface" E2 —
 * native panels render live, not just compile).
 */

class NativePanelErrorBoundary extends React.Component<
  { fallback: React.ReactNode; children: React.ReactNode },
  { hasError: boolean }
> {
  state = { hasError: false };
  static getDerivedStateFromError(): { hasError: true } {
    return { hasError: true };
  }
  render(): React.ReactNode {
    return this.state.hasError ? this.props.fallback : this.props.children;
  }
}

export function NativePanelMount({
  id,
  onClose,
  fallback,
}: {
  /** View id whose VIEW_COMPONENTS[id] native component is mounted. */
  id: string;
  /** Close handler — the chrome the native readout body can't yet express. */
  onClose?: () => void;
  /** Hand-written panel rendered if the native component is absent or throws. */
  fallback: React.ReactNode;
}): React.ReactElement {
  const Native = VIEW_COMPONENTS[id] as React.ComponentType<unknown> | undefined;
  if (!Native) return <>{fallback}</>;
  return (
    <NativePanelErrorBoundary fallback={fallback}>
      <div className="relative h-full">
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            aria-label="Close panel"
            className="absolute right-2 top-2 z-10 rounded p-1 text-studio-muted hover:text-studio-text"
          >
            <X className="h-4 w-4" />
          </button>
        )}
        <Suspense fallback={<div className="p-3 text-[10px] text-studio-muted">Loading…</div>}>
          <Native />
        </Suspense>
      </div>
    </NativePanelErrorBoundary>
  );
}
